css/mic-b12.css:
.mic-b12-page .wellness-product-main {
  width: 100%;
}

/* Keep the surrounding content aligned while the photo spans the page. */
.mic-b12-page .wellness-product-main > :not(.mic-b12-benefits) {
  width: min(100% - 2 * var(--pp-page-gutter), var(--pp-shell-max));
  margin-inline: auto;
}

.mic-b12-benefits {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 85vh;
  min-height: 85svh;
  isolation: isolate;
  overflow: hidden;
  margin-top: clamp(80px, 10vw, 160px);
  padding-block: clamp(88px, 10vw, 144px);
  padding-inline: max(var(--pp-page-gutter), calc((100% - var(--pp-shell-max)) / 2));
  background: var(--pp-warm-ivory);
}

/* Decorative backdrop fills the section without affecting its text-driven height. */
.mic-b12-benefits-media {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.mic-b12-benefits-media img {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 60%;
}

.mic-b12-benefits-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg,
    rgba(246, 244, 240, .84) 0%,
    rgba(246, 244, 240, .72) 55%,
    rgba(246, 244, 240, .6) 100%);
}

.mic-b12-benefits-copy {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1120px;
  min-width: 0;
}

.mic-b12-benefits h2 {
  margin: 0;
  color: var(--pp-prime-navy);
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  font-size: clamp(36px, 4.4vw, 68px);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -.04em;
  text-transform: uppercase;
}

.mic-b12-benefits h2 span {
  display: block;
  color: inherit;
}

.mic-b12-benefits-list {
  --mic-benefits-check-size: clamp(24px, 2.2vw, 30px);
  display: grid;
  gap: clamp(20px, 2vw, 28px);
  margin: clamp(32px, 3.5vw, 48px) 0 0;
  padding: 0;
  list-style: none;
  color: var(--pp-prime-navy);
  font-size: clamp(18px, 2vw, 26px);
  font-weight: 400;
  line-height: 1.5;
}

.mic-b12-benefits-list li {
  display: grid;
  grid-template-columns: var(--mic-benefits-check-size) minmax(0, 1fr);
  align-items: start;
  gap: clamp(14px, 1.5vw, 18px);
}

.mic-b12-benefits-check {
  position: relative;
  width: var(--mic-benefits-check-size);
  height: var(--mic-benefits-check-size);
  margin-top: .12em;
  border: 2px solid currentColor;
  border-radius: 6px;
}

.mic-b12-benefits-check::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 7px;
  height: 12px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translate(-50%, -60%) rotate(45deg);
}

.mic-b12-benefits-list p {
  margin: 0;
}

.mic-b12-benefits-list strong {
  color: inherit;
  font-weight: 700;
}

@media (max-width: 760px) {
  .mic-b12-benefits {
    margin-top: 72px;
    padding-block: 64px;
  }

  .mic-b12-benefits-copy {
    width: 100%;
  }

  .mic-b12-benefits-media img {
    object-position: 62% center;
  }

  .mic-b12-benefits-media::after {
    background: linear-gradient(180deg,
      rgba(246, 244, 240, .82),
      rgba(246, 244, 240, .72));
  }

  .mic-b12-benefits h2 {
    font-size: clamp(30px, 7.5vw, 48px);
  }

  .mic-b12-benefits-list {
    margin-top: 32px;
    gap: 24px;
  }
}

.mic-b12-science {
  margin-top: clamp(80px, 10vw, 160px);
}

.mic-b12-science-heading {
  margin-bottom: 36px;
}

.mic-b12-science-heading h2 {
  margin: 0;
  font: 400 clamp(36px, 3.8vw, 58px)/1.12 Georgia, "Times New Roman", serif;
  letter-spacing: -.035em;
}

.mic-b12-science-heading h2 span {
  color: var(--pp-prime-gold);
}

.mic-b12-science-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.mic-b12-science-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: clamp(22px, 2.6vw, 40px);
  border: 1px solid var(--pp-gold-soft);
  border-radius: 20px;
  background: rgba(255,255,255,.38);
}

.mic-b12-science-card h3 {
  margin: 0;
  min-height: 2.4em;
  font: 400 clamp(23px, 2.1vw, 32px)/1.2 Georgia, "Times New Roman", serif;
  letter-spacing: -.02em;
}

/* Width determines each square photo; longer descriptions cannot stretch it. */
.mic-b12-science-art {
  position: relative;
  flex: 0 0 auto;
  margin: 30px 0;
  padding: 24px;
  border: 1px solid var(--pp-gold-soft);
  border-radius: 18px;
}

.mic-b12-science-art img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 1;
  object-fit: cover;
  border-radius: 12px;
  box-shadow: 0 12px 26px rgba(15,31,45,.09);
}

.mic-b12-science-card p {
  margin: 0;
  color: var(--pp-prime-navy);
  font-size: 1rem;
  line-height: 1.65;
}

.mic-b12-quality {
  display: grid;
  grid-template-columns: minmax(0, .94fr) minmax(0, 1.06fr);
  gap: clamp(42px, 6vw, 96px);
  align-items: start;
  margin-top: clamp(96px, 10vw, 168px);
}

/* Measured from collapsed copy; accordion expansion never resizes this frame. */
.mic-b12-quality-media {
  position: relative;
  width: 100%;
  height: var(--product-photo-height, auto);
  aspect-ratio: 2 / 3;
  min-height: 0;
  overflow: hidden;
  border: 1px solid rgba(198,157,82,.25);
  border-radius: clamp(22px, 2vw, 32px);
  background: #ece7dd;
  box-shadow: 0 24px 60px rgba(15,31,45,.1);
}

.mic-b12-quality-media img {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.mic-b12-quality-content {
  min-width: 0;
}

.mic-b12-quality-eyebrow {
  margin: 0 0 18px;
  color: var(--pp-prime-gold);
  font-size: clamp(.72rem, .78vw, .84rem);
  font-weight: 700;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.mic-b12-quality h2 {
  margin: 0;
  font: 400 clamp(2.7rem, 4.8vw, 5.4rem)/.98 Georgia, "Times New Roman", serif;
  letter-spacing: -.045em;
}

.mic-b12-quality h2 span {
  color: var(--pp-prime-gold);
}

.mic-b12-quality-intro {
  margin: clamp(22px, 2.5vw, 34px) 0 0;
  color: var(--pp-prime-navy);
  font-size: clamp(1rem, 1.1vw, 1.16rem);
  line-height: 1.7;
}

.mic-b12-quality-list {
  display: grid;
  margin-top: clamp(26px, 3vw, 40px);
}

.mic-b12-quality-list details {
  border-top: 1px solid rgba(15,31,45,.13);
}

.mic-b12-quality-list details:last-child {
  border-bottom: 1px solid rgba(15,31,45,.13);
}

.mic-b12-quality-list summary {
  display: flex;
  min-height: 72px;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 0;
  cursor: pointer;
  font: 400 clamp(1.22rem, 1.5vw, 1.58rem)/1.15 Georgia, "Times New Roman", serif;
  list-style: none;
}

.mic-b12-quality-list summary::-webkit-details-marker {
  display: none;
}

.mic-b12-quality-list summary:focus-visible {
  outline: 2px solid var(--pp-prime-gold);
  outline-offset: 4px;
}

.mic-b12-quality-toggle {
  position: relative;
  display: grid;
  place-items: center;
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(198,157,82,.65);
  border-radius: 50%;
  background: rgba(198,157,82,.08);
}

.mic-b12-quality-toggle::before,
.mic-b12-quality-toggle::after {
  content: "";
  position: absolute;
  width: 14px;
  height: 1.5px;
  background: #9a712f;
}

.mic-b12-quality-toggle::after {
  transform: rotate(90deg);
}

.mic-b12-quality-list details[open] .mic-b12-quality-toggle::after {
  transform: rotate(0);
}

.mic-b12-quality-list p {
  margin: -2px 62px 20px 0;
  color: var(--pp-prime-navy);
  font-size: clamp(.92rem, 1vw, 1.04rem);
  line-height: 1.6;
}

@media (max-width: 760px) {
  .mic-b12-science {
    margin-top: 72px;
  }

  .mic-b12-science-grid {
    grid-template-columns: 1fr;
  }

  .mic-b12-science-card {
    padding: 26px;
  }

  .mic-b12-science-card h3 {
    min-height: 0;
    font-size: 28px;
  }

  .mic-b12-quality {
    grid-template-columns: 1fr;
    gap: 36px;
    margin-top: 72px;
  }

  .mic-b12-quality-media {
    height: auto;
    aspect-ratio: 4 / 3;
  }

  .mic-b12-quality-media img {
    object-position: center 20%;
  }
}

.mic-b12-faq-section {
  margin-top: clamp(80px, 8vw, 128px);
}

.mic-b12-faq-section > h2 {
  margin: 0 0 clamp(36px, 4.5vw, 64px);
  color: var(--pp-prime-navy);
  font-size: clamp(2.6rem, 4.3vw, 5rem);
  font-weight: 430;
  line-height: 1;
  letter-spacing: -.05em;
  text-align: center;
}

.mic-b12-faq-section > h2 span {
  color: var(--pp-prime-gold);
}

.mic-b12-faq-list {
  display: grid;
  gap: clamp(16px, 1.7vw, 24px);
}

.mic-b12-faq-item {
  overflow: hidden;
  border: 1px solid rgba(var(--pp-gold-rgb), .2);
  border-radius: clamp(18px, 1.8vw, 28px);
  background: var(--pp-warm-ivory);
  color: #0f1f2d;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .72), 0 16px 34px rgba(0, 0, 0, .12);
}

.mic-b12-faq-item summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 32px;
  align-items: center;
  gap: 24px;
  min-height: clamp(70px, 5.5vw, 86px);
  padding: clamp(16px, 1.6vw, 22px) clamp(24px, 2.8vw, 42px);
  font-size: clamp(1.12rem, 1.55vw, 1.55rem);
  font-weight: 400;
  line-height: 1.22;
  list-style: none;
  cursor: pointer;
}

.mic-b12-faq-item summary::-webkit-details-marker { display: none; }
.mic-b12-faq-item summary:focus-visible { outline: 3px solid rgba(var(--pp-gold-rgb), .65); outline-offset: -6px; }

.mic-b12-faq-icon {
  position: relative;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(155, 106, 36, .42);
  border-radius: 50%;
  background: rgba(var(--pp-gold-rgb), .1);
}

.mic-b12-faq-icon::before,
.mic-b12-faq-icon::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 13px;
  height: 2px;
  border-radius: 999px;
  background: #8f6927;
  transform: translate(-50%, -50%);
  transition: transform 180ms ease;
}

.mic-b12-faq-icon::after { transform: translate(-50%, -50%) rotate(90deg); }
.mic-b12-faq-item[open] .mic-b12-faq-icon::after { transform: translate(-50%, -50%); }

.mic-b12-faq-answer {
  margin: 0 clamp(26px, 3vw, 46px);
  padding: clamp(22px, 2.2vw, 32px) 0 clamp(28px, 3vw, 42px);
  border-top: 1px solid rgba(155, 106, 36, .2);
}

.mic-b12-faq-answer p {
  max-width: 1080px;
  margin: 0;
  color: var(--pp-prime-navy);
  font-size: clamp(.98rem, 1.16vw, 1.18rem);
  font-weight: 400;
  line-height: 1.65;
}

@media (prefers-reduced-motion: reduce) {
  .mic-b12-faq-icon::before,
  .mic-b12-faq-icon::after { transition: none; }
}

@media (max-width: 760px) {
  .mic-b12-faq-section > h2 { font-size: clamp(2.3rem, 11vw, 3.15rem); }
  .mic-b12-faq-item summary { grid-template-columns: minmax(0, 1fr) 30px; gap: 16px; min-height: 64px; padding: 16px 18px; }
  .mic-b12-faq-icon { width: 30px; height: 30px; }
  .mic-b12-faq-answer { margin: 0 20px; padding: 20px 0 28px; }
}
